// Implicit declarations (automatic, no #include needed):
void* operator new(std::size_t);
void* operator new[](std::size_t);
void operator delete(void*) noexcept;
void operator delete[](void*) noexcept;
void operator delete(void*, std::size_t) noexcept;     // Sized delete (C++14)
void operator delete[](void*, std::size_t) noexcept;   // Sized delete (C++14)

// Usage (new/delete expressions):
Widget* w = new Widget;           // Calls: operator new, then constructor
delete w;                          // Calls: destructor, then operator delete

Widget* arr = new Widget[10];     // Calls: operator new[], then 10 constructors
delete[] arr;                      // Calls: 10 destructors, then operator delete[]

// Placement new (no allocation):
void* buffer = malloc(sizeof(Widget));
Widget* w2 = new (buffer) Widget;  // Construct at existing address
w2->~Widget();                     // Manual destructor call
free(buffer);                      // Manual deallocation

