#include <iostream>
#include <new>      // For std::size_t, std::nothrow
#include <cstdlib>  // For malloc/free

// Track allocations for demonstration
static size_t allocation_count = 0;
static size_t deallocation_count = 0;

// Replace global operator new (allowed: at most ONE definition)
void* operator new(std::size_t size) {
    allocation_count++;
    std::cout << "Custom operator new: " << size << " bytes\n";
    void* ptr = std::malloc(size);
    if (!ptr) throw std::bad_alloc();
    return ptr;
}

// Replace global operator delete
void operator delete(void* ptr) noexcept {
    deallocation_count++;
    std::cout << "Custom operator delete\n";
    std::free(ptr);
}

// Optional: Sized delete (C++14)
void operator delete(void* ptr, std::size_t size) noexcept {
    deallocation_count++;
    std::cout << "Custom operator delete (sized): " << size << " bytes\n";
    std::free(ptr);
}

class Widget {
public:
    Widget() { std::cout << "  Widget() constructor\n"; }
    ~Widget() { std::cout << "  ~Widget() destructor\n"; }
    int data[10];  // Make it non-trivial size
};

int main() {
    std::cout << "=== Dynamic Storage Duration Demo ===\n\n";

    // new-expression: calls operator new, then constructor
    std::cout << "Creating Widget with new:\n";
    Widget* w = new Widget;

    std::cout << "\nDeleting Widget:\n";
    delete w;  // Calls destructor, then operator delete

    // Array allocation
    std::cout << "\nCreating Widget array:\n";
    Widget* arr = new Widget[3];

    std::cout << "\nDeleting Widget array:\n";
    delete[] arr;

    // Placement new (no allocation)
    std::cout << "\nPlacement new (no allocation):\n";
    void* buffer = std::malloc(sizeof(Widget));
    Widget* w2 = new (buffer) Widget;  // Construct at existing address

    std::cout << "\nManual destruction for placement new:\n";
    w2->~Widget();  // Manual destructor
    std::free(buffer);  // Manual deallocation (NO operator delete)

    std::cout << "\n=== Statistics ===\n";
    std::cout << "Allocations: " << allocation_count << "\n";
    std::cout << "Deallocations: " << deallocation_count << "\n";

    return 0;
}

// Output:
// === Dynamic Storage Duration Demo ===
//
// Creating Widget with new:
// Custom operator new: 40 bytes
//   Widget() constructor
//
// Deleting Widget:
//   ~Widget() destructor
// Custom operator delete (sized): 40 bytes
//
// Creating Widget array:
// Custom operator new: 128 bytes  <- Extra bytes for array metadata
//   Widget() constructor
//   Widget() constructor
//   Widget() constructor
//
// Deleting Widget array:
//   ~Widget() destructor
//   ~Widget() destructor
//   ~Widget() destructor
// Custom operator delete
//
// Placement new (no allocation):
//   Widget() constructor
//
// Manual destruction for placement new:
//   ~Widget() destructor
//
// === Statistics ===
// Allocations: 2      <- new Widget + new Widget[3], NOT placement
// Deallocations: 2
